package com.fandazi.feature.address;
import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/addresses") public class AddressController { private final AddressService addresses; public AddressController(AddressService addresses){this.addresses=addresses;} @GetMapping public List<AddressResponse> list(@AuthenticationPrincipal Long userId){return addresses.list(userId).stream().map(AddressResponse::from).toList();}@PostMapping public ResponseEntity<AddressResponse> create(@AuthenticationPrincipal Long userId,@Valid @RequestBody AddressCommand command){return ResponseEntity.status(HttpStatus.CREATED).body(AddressResponse.from(addresses.create(userId,command)));}@PutMapping("/{id}") public AddressResponse update(@AuthenticationPrincipal Long userId,@PathVariable Long id,@Valid @RequestBody AddressCommand command){return AddressResponse.from(addresses.update(userId,id,command));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@AuthenticationPrincipal Long userId,@PathVariable Long id){addresses.delete(userId,id);}@PatchMapping("/{id}/default") public AddressResponse setDefault(@AuthenticationPrincipal Long userId,@PathVariable Long id){return AddressResponse.from(addresses.setDefault(userId,id));} }
